from typing import List

def zigzagTraversal(grid: List[List[int]]) -> List[int]:
    result = []
    for i in range(len(grid)):
        if i % 2 == 0:
            # Traverse right on even rows
            for j in range(0, len(grid[i]), 2):
                result.append(grid[i][j])
        else:
            # Traverse left on odd rows
            for j in range(0, len(grid[i]), 2):
                result.append(grid[i][len(grid[i]) - j - 1])
    return result

from collections import Counter

def maxDifference(s: str) -> int:
    freq = Counter(s)
    odd_freq = [count for count in freq.values() if count % 2 == 1]
    even_freq = [count for count in freq.values() if count % 2 == 0]
    return max(odd_freq) - min(even_freq)

from typing import List

def sumOfGoodNumbers(nums: List[int], k: int) -> int:
    total_sum = 0
    n = len(nums)
    for i in range(n):
        is_good = True
        if i - k >= 0 and nums[i] <= nums[i - k]:
            is_good = False
        if i + k < n and nums[i] <= nums[i + k]:
            is_good = False
        if is_good:
            total_sum += nums[i]
    return total_sum

def hasSpecialSubstring(s: str, k: int) -> bool:
    n = len(s)
    if k > n:
        return False
    for i in range(n - k + 1):
        substring = s[i:i + k]
        if len(set(substring)) == 1:
            left_condition = (i == 0 or s[i - 1] != substring[0])
            right_condition = (i + k == n or s[i + k] != substring[0])
            if left_condition and right_condition:
                return True
    return False

