from typing import List


def totalNumbers(digits: List[int]) -> int:
    from itertools import permutations
    distinct_numbers = set()
    for perm in permutations(digits, 3):
        if perm[0] != 0 and perm[2] % 2 == 0:
            distinct_numbers.add(perm)
    return len(distinct_numbers)

from typing import List

def maxSum(nums: List[int]) -> int:
    unique_nums = set()
    total_sum = 0
    for num in nums:
        if num > 0:
            if num not in unique_nums:
                unique_nums.add(num)
                total_sum += num
    return total_sum if total_sum > 0 else max(nums)

from typing import List


def longestSubsequence(nums: List[int]) -> int:
    n = len(nums)
    dp = [1] * n  # Store the length of the longest subsequence ending at each index
    max_length = 1  # At least one element exists in the subsequence

    for i in range(n):
        for j in range(i):
            diff = abs(nums[i] - nums[j])
            if j == 0 or abs(nums[j] - nums[j-1]) >= diff:
                dp[i] = max(dp[i], dp[j] + 1)
                max_length = max(max_length, dp[i])
    return max_length

from collections import defaultdict

def calculateScore(s: str) -> int:
    score = 0
    available_indices = defaultdict(list)
    mirror = {chr(i): chr(219 - i) for i in range(97, 123)}  # Create mirror mapping

    for i, char in enumerate(s):
        target = mirror[char]
        if available_indices[target]:
            j = available_indices[target].pop()
            score += i - j
        else:
            available_indices[char].append(i)

    return score

from typing import List

def maximumAmount(coins: List[List[int]]) -> int:
    m, n = len(coins), len(coins[0])
    # dp[i][j][k] represents the maximum coins we can collect to reach (i, j) with k neutralizations used.
    dp = [[[-float('inf')] * 3 for _ in range(n)] for _ in range(m)]
    dp[0][0][0] = coins[0][0]  # Starting point
    if coins[0][0] < 0:
        # We can use one neutralization at the start for a score of 0.
        dp[0][0][1] = 0

    for i in range(m):
        for j in range(n):
            for k in range(3):
                if i == 0 and j == 0:
                    continue  # Skip the starting point
                # Collect coins from the upper cell
                if i > 0:
                    coin_value = coins[i][j]
                    if coin_value < 0 and k > 0:
                        dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k-1])  # Neutralize robbery
                    else:
                        dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k] + coin_value)
                # Collect coins from the left cell
                if j > 0:
                    coin_value = coins[i][j]
                    if coin_value < 0 and k > 0:
                        dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k-1])  # Neutralize robbery
                    else:
                        dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k] + coin_value)

    # The maximum coins we can collect to reach (m-1, n-1) with at most 2 neutralizations
    return max(dp[m-1][n-1][0], dp[m-1][n-1][1], dp[m-1][n-1][2])

