from collections import defaultdict, deque


def minMaxWeight(n: int, edges: List[List[int]], threshold: int) -> int:
    edges.sort(key=lambda x: x[2])  # Sort edges by weight

    def can_construct(max_weight: int) -> bool:
        graph = defaultdict(list)
        out_degree = [0] * n

        # Build the graph with edges under max_weight constraint
        for u, v, w in edges:
            if w <= max_weight:
                graph[u].append(v)
                # Count outgoing edges considering threshold
                if out_degree[u] < threshold:
                    out_degree[u] += 1
                else:
                    graph[u].pop()  # Remove edge if threshold exceeded

        # Check reachability from node 0 using reversed graph
        reachable = set()
        queue = deque([0])  # Start BFS from node 0
        while queue:
            node = queue.popleft()
            if node not in reachable:
                reachable.add(node)
                for neighbor in graph[node]:  # Explore neighbors
                    if neighbor not in reachable:
                        queue.append(neighbor)

        # Ensure all nodes can reach node 0
        if len(reachable) != n:
            return False

        # Now check that we can select edges to satisfy the out_degree constraint
        selected_out_degree = [0] * n
        for u in range(n):
            if out_degree[u] > threshold:
                return False
            for v in graph[u]:
                if selected_out_degree[u] < threshold:
                    selected_out_degree[u] += 1

        return True

    left, right = 1, 10**6  # Minimum and maximum possible edge weights
    result = -1

    while left <= right:
        mid = (left + right) // 2
        if can_construct(mid):
            result = mid
            right = mid - 1  # Try for a smaller max weight
        else:
            left = mid + 1  # Increase max weight

    return result

