from typing import List

def minCost(n: int, cost: List[List[int]]) -> int:
    # Define a 2D DP array to hold the minimum costs
    dp = [[0] * 3 for _ in range(n)]
    # Initialize the first house with the given costs
    for j in range(3):
        dp[0][j] = cost[0][j]

    # Fill the dp array for all houses considering adjacency and equidistant constraints
    for i in range(1, n):
        for j in range(3):
            # Minimum cost for painting house i with color j
            min_cost = float('inf')
            for k in range(3):
                if k != j:
                    min_cost = min(min_cost, dp[i-1][k])
            dp[i][j] = min_cost + cost[i][j]

    # Handle the equidistant constraints for the first half
    for i in range(n // 2):
        for j in range(3):
            equidistant_index = n - i - 1
            for k in range(3):
                if k != j:
                    dp[equidistant_index][j] = min(dp[equidistant_index][j], dp[i][k])

    # The answer will be the minimum cost of painting all houses, considering the last house
    return min(dp[n-1][0], dp[n-1][1], dp[n-1][2])

